package com.example;import org.springframework.context.annotation.*;import org.springframework.context.support.ClassPathXmlApplicationContext;public class MainApp {public static void main(String[] args){try(var xml=new ClassPathXmlApplicationContext("beans.xml")){xml.getBean("student",Student.class).show();}try(var ctx=new AnnotationConfigApplicationContext(AppConfig.class)){ctx.getBean(Teacher.class).teach();}}}
